I'll implement the longest substring without repeating characters using a sliding window approach, then explain Unicode handling and provide tests.

```js
function longestSubstring(s) {
    if (s.length === 0) return 0;

    let start = 0;
    let maxLength = 0;
    const charIndexMap = new Map();

    for (let end = 0; end < s.length; end++) {
        const currentChar = s[end];

        // If character is already in the map and its index is >= start, move start
        if (charIndexMap.has(currentChar) && charIndexMap.get(currentChar) >= start) {
            start = charIndexMap.get(currentChar) + 1;
        }

        // Update the character's latest index
        charIndexMap.set(currentChar, end);

        // Update maxLength if needed
        maxLength = Math.max(maxLength, end - start + 1);
    }

    return maxLength;
}
```

