```js
/**
 * Checks if a string has valid bracket nesting for (), [], and {}.
 * Non-bracket characters are ignored.
 * @param {string} s - Input string to check
 * @returns {boolean} True if all brackets are properly nested and closed, false otherwise
 */
function isValidBrackets(s) {
  // Handle non-string input
  if (typeof s !== 'string') {
    return false;
  }

  const stack = [];
  const bracketPairs = {
    '(': ')',
    '[': ']',
    '{': '}'
  };

  for (let i = 0; i < s.length; i++) {
    const char = s[i];

    // If it's an opening bracket, push to stack
    if (bracketPairs.hasOwnProperty(char)) {
      stack.push(char);
    } 
    // If it's a closing bracket
    else if (char === ')' || char === ']' || char === '}') {
      // If stack is empty, there's no matching opening bracket
      if (stack.length === 0) {
        return false;
      }

      const lastOpening = stack.pop();
      const expectedClosing = bracketPairs[lastOpening];

      // If the closing bracket doesn't match the last opening
      if (char !== expectedClosing) {
        return false;
      }
    }
    // Ignore any other characters
  }

  // If stack isn't empty, some brackets weren't closed
  return stack.length === 0;
}
