```js
/**
 * Performs an iterative binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number>} sorted - The sorted array to search in (ascending order)
 * @param {number} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * 
 * Requirements:
 * - Time Complexity: O(log n)
 * - Space Complexity: O(1)
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Uses safe midpoint computation: left + Math.floor((right - left) / 2)
 * 
 * Note: The input array must be sorted in ascending order. If the target is not present, returns -1.
 */
function binarySearch(sorted, target) {
    let left = 0;
    let right = sorted.length - 1;
    let result = -1;

    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);

        if (sorted[mid] === target) {
            result = mid; // Record the position and continue searching left
            right = mid - 1;
        } else if (sorted[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return result;
}

/**
 * Performs a recursive binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number>} sorted - The sorted array to search in (ascending order)
 * @param {number} target - The value to search for
 * @param {number} [left=0] - The left boundary of the search range (internal use)
 * @param {number} [right=sorted.length-1] - The right boundary of the search range (internal use)
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * 
 * Requirements:
 * - Time Complexity: O(log n)
 * - Space Complexity: O(log n) due to recursion stack
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Uses safe midpoint computation: left + Math.floor((right - left) / 2)
 * - Safe for null/undefined input (validation in function body)
 * 
 * Note: The input array must be sorted in ascending order. If the target is not present, returns -1.
 */
function binarySearchRecursive(sorted, target, left = 0, right = sorted.length - 1) {
    // Validate input
    if (!sorted || !Array.isArray(sorted) || sorted.length === 0) {
        return -1;
    }

    // Adjust right boundary if it's beyond array length
    right = Math.min(right, sorted.length - 1);

    if (left > right) {
        return -1;
    }

    const mid = left + Math.floor((right - left) / 2);

    if (sorted[mid] === target) {
        // Check if this is the first occurrence
        if (mid === 0 || sorted[mid - 1] < target) {
            return mid;
        }
        // Continue searching left
        return binarySearchRecursive(sorted, target, left, mid - 1);
    } else if (sorted[mid] < target) {
        return binarySearchRecursive(sorted, target, mid + 1, right);
    } else {
        return binarySearchRecursive(sorted, target, left, mid - 1);
    }
}
```

### Explanation:

**Iterative Version:**
- Uses a while loop to narrow down the search range
- Maintains a `result` variable to track the first occurrence of the target
- When the target is found, it continues searching to the left to find the first occurrence
- Time complexity: O(log n) - halves the search space each iteration
- Space complexity: O(1) - uses a constant amount of extra space

**Recursive Version:**
- Uses recursion to implement the binary search
- Includes default parameters for left and right boundaries
- Validates input at the start to handle null/undefined safely
- When the target is found, it checks if it's the first occurrence by looking at the previous element
- If not the first occurrence, continues searching to the left
- Time complexity: O(log n) - halves the search space with each recursive call
- Space complexity: O(log n) - due to the recursion stack

**Boundary Cases:**
- Empty array: returns -1
- Target not present: returns -1
- Single element array: returns 0 if element matches, otherwise -1
- All elements are the same: returns 0
- Target is smaller than all elements: returns -1
- Target is larger than all elements: returns -1

**Index Convention:**
- Uses standard JavaScript array indexing (0-based)
- Returns the first occurrence when duplicates exist

**Input Purity:**
- Neither function mutates or sorts the input array
- The input array remains unchanged after the function call

Both implementations meet the specified time and space complexity requirements and correctly handle finding the first occurrence of the target in a sorted array with duplicates.

